<?php get_header(); ?><main class="site-width content-layout"><article class="site-main" id="content"><?php if (have_posts()): while (have_posts()): the_post(); $categories = get_the_category(); $is_recipe = str_contains((string) get_post_field('post_content', get_the_ID()), 'data-recipe-card'); ?><header class="entry-header"><?php if ($categories): ?><a class="entry-category" href="<?php echo esc_url(get_category_link($categories[0])); ?>"><?php echo esc_html($categories[0]->name); ?></a><?php endif; ?><h1 class="entry-title"><?php the_title(); ?></h1><div class="entry-meta">By <?php the_author_posts_link(); ?> · <?php echo esc_html(get_the_date()); ?></div></header><div class="entry-content"><?php the_content(); ?></div><?php if ($is_recipe): ?><section class="askinz-standards" aria-label="Askinz recipe standards" style="margin:2rem 0;padding:1.25rem;border:1px solid #d8e5cc;border-radius:16px;background:#f5f8f1;"><p style="margin:0 0 .35rem;color:#315d37;font-weight:800;letter-spacing:.08em;text-transform:uppercase;font-size:.78rem;">Askinz Standards</p><h2 style="margin:.1rem 0 .55rem;color:#263c2d;font-family:Georgia,serif;font-size:1.45rem;">Practical recipes for real kitchens.</h2><p style="margin:0;color:#4b5548;line-height:1.7;">We aim to make every recipe easy to follow, with clear steps and useful swaps, storage, or serving guidance where it helps you cook with confidence.</p></section><section class="askinz-engagement" aria-label="Recipe conversation" style="margin:2rem 0;padding:1.25rem;border:1px solid #eadfcd;border-radius:16px;background:#fffaf2;"><h2 style="margin:0 0 .45rem;color:#263c2d;font-family:Georgia,serif;font-size:1.4rem;">Did you make it your way?</h2><p style="margin:0;color:#5e6358;line-height:1.7;">Tell other home cooks which swap you used, what you served alongside it, or what helped in your kitchen.</p><a href="#respond" style="display:inline-block;margin-top:.8rem;color:#315d37;font-weight:800;">Share a useful note in the comments →</a></section><?php $related_categories = wp_list_pluck($categories, 'term_id'); $related = new WP_Query(array('post_type'=>'post','posts_per_page'=>3,'post__not_in'=>array(get_the_ID()),'category__in'=>$related_categories,'ignore_sticky_posts'=>true,'no_found_rows'=>true)); if ($related->have_posts()): global $askinz_card_loading_context; $askinz_card_loading_context = 'related'; ?><section class="askinz-related-recipes" aria-label="Related recipes" style="margin:2.5rem 0;"><div class="section-heading"><div><p class="eyebrow">Keep cooking</p><h2>You might also enjoy</h2></div></div><div class="post-grid"><?php while ($related->have_posts()): $related->the_post(); get_template_part('template-parts/content','card'); endwhile; ?></div></section><?php $askinz_card_loading_context = null; wp_reset_postdata(); endif; endif; ?><nav class="post-navigation" aria-label="Post navigation"><?php the_post_navigation(array('prev_text'=>'← %title','next_text'=>'%title →')); ?></nav><?php comments_template(); endwhile; endif; ?></article><?php get_sidebar(); ?></main><?php get_footer(); ?>
